def find_affine(srcs, outs):
 found=[]
 # output position maps source at corresponding index
 for a in range(8):
  for b in range(8):
   for c in range(8):
    for d in range(8):
     if (a*d-b*c)%2==0: continue
     for e in range(8):
      for f in range(8):
       ok=True
       rr,cc=np.indices((8,8))
       ri=(a*rr+b*cc+e)%8; ci=(c*rr+d*cc+f)%8
       for s,o in zip(srcs,outs):
        if not np.array_equal(s[ri,ci],o): ok=False; break
       if ok: found.append((a,b,c,d,e,f))
 return found
